// src/App.js
import React from 'react';
import RegistrationForm from './components/RegistrationForm'; 
import LoginForm from './components/LoginForm';
// Impor Provider dan Komponen Tema yang baru dibuat
import { AdvancedThemeProvider, useAdvancedTheme } from './context/AdvancedThemeContext';
import AdvancedThemeControls from './components/AdvancedThemeControls';

// Buat komponen pembungkus (Wrapper) untuk mengonsumsi tema
function AppContent() {
  const { colors } = useAdvancedTheme();

  return (
    // Gunakan warna dari Context API untuk styling background
    <div style={{ backgroundColor: colors.background, minHeight: '100vh', padding: '2rem 1rem' }}>

      <div style={{ maxWidth: '800px', margin: '0 auto' }}>
        <h1 style={{ color: colors.primary, textAlign: 'center' }}>Sistem Informasi Manajemen</h1>

        {/* Panel Kontrol Tema (Acara 13) */}
        <AdvancedThemeControls />

        {/* Garis pemisah */}
        <hr style={{ margin: '2rem 0', borderColor: colors.border }} />

        <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>
          {/* Form Registrasi (Dari Minggu Sebelumnya) */}
          <RegistrationForm />

          {/* Form Login (Dari Minggu Sebelumnya) */}
          <LoginForm />
        </div>
      </div>

    </div>
  );
}

// Bungkus AppContent dengan Provider
function App() {
  return (
    <AdvancedThemeProvider>
      <AppContent />
    </AdvancedThemeProvider>
  );
}

export default App;
